#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# The library above this marker is copied verbatim from the wizard skill.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

banner "The Builder: Firebase Hosting cutover"
say "Project: the-builder-12fe5. Stop if the admin site ID is unavailable."
say "Run this from the repository root after the monorepo changes are committed and pushed."
pause "Press Enter when the branch containing the deploy workflows is on GitHub."

stage "Create the admin Hosting site"
open_url "https://console.firebase.google.com/project/the-builder-12fe5/hosting"
step "Confirm site ID the-builder-12fe5-admin exists. If absent, choose Add another site and enter that exact ID."
step "Keep the existing default site the-builder-12fe5 for home."
step "If this exact admin ID is already taken globally, stop and agree on a new ID before editing .firebaserc or deploying."
confirm "Does the admin site now exist with the exact planned ID?" || exit 1

stage "Authorize both admin origins for Firebase Auth"
open_url "https://console.firebase.google.com/project/the-builder-12fe5/authentication/settings"
step "Under Authorized domains, confirm admin.thebuilder.co.id and the-builder-12fe5-admin.web.app; add either if missing."
step "Keep existing production and localhost entries."
confirm "Are both admin domains listed under Authorized domains?" || exit 1

stage "Allow Hosting origins on the App Check reCAPTCHA key"
open_url "https://console.cloud.google.com/security/recaptcha?project=the-builder-12fe5"
step "Open the website key matching VITE_FIREBASE_APPCHECK_SITE_KEY, then Edit key."
step "Confirm admin.thebuilder.co.id, the-builder-12fe5-admin.web.app, and the-builder-12fe5.web.app are allowed; add missing entries."
step "Keep thebuilder.co.id and localhost. Save; changes can take time to propagate."
confirm "Are the production, Firebase web.app, and local origins permitted by that key?" || exit 1

stage "Create a Hosting deploy service account and GitHub secret"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=the-builder-12fe5"
step "Use the existing thebuilder-hosting-deploy service account created for this workflow."
step "It has Firebase Hosting Admin and Service Usage API Keys Viewer. Create and download a JSON key for it."
step "Keep the JSON private. Enter its local path; the script reads it without printing the contents."
ask SERVICE_ACCOUNT_FILE "Path to downloaded JSON key:"
[[ -f "$SERVICE_ACCOUNT_FILE" && -r "$SERVICE_ACCOUNT_FILE" ]] || { warn "JSON key file is not readable"; exit 1; }
open_url "https://github.com/boypanjaitan16/thebuilder/settings/secrets/actions"
step "This workflow also needs the existing VITE_FIREBASE_* repository secrets from the old Pages workflow. Check all eight names in .github/workflows/deploy-home.yml and deploy-admin.yml."
step "If gh is installed and authenticated, the next step sets FIREBASE_SERVICE_ACCOUNT. Otherwise paste the JSON file content into a new repository secret with that name."
set_secret FIREBASE_SERVICE_ACCOUNT "$(cat "$SERVICE_ACCOUNT_FILE")"
confirm "Is FIREBASE_SERVICE_ACCOUNT set in GitHub Actions, along with all required VITE_FIREBASE_* secrets?" || exit 1

stage "Deploy the same revision to both Firebase sites"
open_url "https://github.com/boypanjaitan16/thebuilder/actions/workflows/deploy-home.yml"
step "Run the manual home workflow on the branch containing this migration. Wait for lint, tests, build, and Deploy home to pass."
open_url "https://github.com/boypanjaitan16/thebuilder/actions/workflows/deploy-admin.yml"
step "Run the manual admin workflow on the same branch. Wait for lint, tests, build, and Deploy admin to pass."
step "Both targets must show the same commit SHA. Do not switch DNS if either deploy failed."
confirm "Did both Hosting deploy steps pass on the same revision?" || exit 1

stage "Check Firebase domains before DNS cutover"
open_url "https://the-builder-12fe5-admin.web.app/login"
step "Check direct reload of /articles/new while signed out (guard should send you to /login). Sign in and verify article/product CRUD and image upload."
step "Check https://the-builder-12fe5.web.app/ for public content, /apply submission, published articles/products while signed out, App Check, and no admin pages."
step "Inspect browser console/network for CSP, App Check, and Firestore errors."
confirm "Have the Firebase-domain smoke checks passed?" || exit 1

stage "Connect custom domains and change DNS"
open_url "https://console.firebase.google.com/project/the-builder-12fe5/hosting"
step "Confirm thebuilder.co.id is registered on site the-builder-12fe5, and admin.thebuilder.co.id on site the-builder-12fe5-admin. Add either if missing."
step "Copy the exact verification TXT and routing A/AAAA/CNAME records shown by Firebase for each domain. Use those values in the DNS provider; do not use guessed record values."
step "Keep verification TXT records, remove only conflicting old routing records, and wait until both domains report Connected with active SSL certificates."
confirm "Have you reviewed both Firebase-provided DNS record sets and are you ready to change production traffic?" || exit 1
pause "After changing DNS and waiting for both certificates, press Enter."
confirm "Do both custom domains now report Connected and serve HTTPS?" || exit 1

stage "Verify production and record rollback point"
open_url "https://admin.thebuilder.co.id/login"
step "Check admin login/guard, nested route reload, product/article CRUD, cover/thumbnail upload, and public View site links."
step "Check https://thebuilder.co.id/admin/articles returns the home 404 with HTTP 404; public routes, /apply, sitemap, and published reads still work."
step "Check GA4 page views come only from home. Save the Firebase Hosting release IDs and keep the prior DNS values for rollback."
step "After the seven-day preview expires, remove its two temporary domains from Firebase Auth and the reCAPTCHA key's allowed-domain list."
confirm "Did all production checks pass?" || exit 1

finish
